import os,sys,json,time
import numpy as np
import rcb_dtb,mujoco
from scipy.spatial.transform import Rotation as Rot
from PIL import Image

class Controller:
 def __init__(self):
  self.s=rcb_dtb.Session();self.m=self.s.model;self.d=self.s.data;self.k=mujoco.MjData(self.m)
  self.b=self.m.body('palmleft_hand_C_MC').id;self.ob=self.m.body('object').id
  self.q=rcb_dtb.INIT_Q.copy();self.s.record_start()
 def pose(self):return self.d.xpos[self.b].copy(),self.d.xmat[self.b].reshape(3,3).copy()
 def ik(self,p,R,q=None):
  q=self.q.copy() if q is None else q.copy();self.k.qpos[:]=self.d.qpos
  for _ in range(60):
   self.k.qpos[self.s._jq]=q;mujoco.mj_forward(self.m,self.k)
   e=np.r_[p-self.k.xpos[self.b],Rot.from_matrix(R@self.k.xmat[self.b].reshape(3,3).T).as_rotvec()]
   if np.linalg.norm(e)<1e-5:break
   jp=np.zeros((3,self.m.nv));jr=jp.copy();mujoco.mj_jacBody(self.m,self.k,jp,jr,self.b)
   J=np.r_[jp[:,:7],jr[:,:7]];dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,e)
   q[:7]+=dq*min(1,.15/(np.max(np.abs(dq))+1e-9));q=np.clip(q,self.s.lower,self.s.upper)
  return q
 def step(self,q):self.q=q.copy();return self.s.step(q)
 def move(self,p,R=None,hand=None,n=120):
  p0,R0=self.pose();R=R0 if R is None else R;rv=Rot.from_matrix(R@R0.T).as_rotvec();h0=self.q[7:].copy();hand=h0 if hand is None else hand
  for i in range(n):
   t=(i+1)/n;t=t*t*(3-2*t)
   q=self.ik(p0+(p-p0)*t,Rot.from_rotvec(t*rv).as_matrix()@R0);q[7:]=h0+(hand-h0)*t;self.step(q)
 def hold(self,n=60):
  for _ in range(n):self.step(self.q)
 def info(self,tag):
  print(tag,'step',self.s.steps,'obj',np.round(self.d.xpos[self.ob],4),'palm',np.round(self.pose()[0],4),'progress',self.s.progress(),flush=True)
  cs=[]
  for c in self.d.contact:
   b1,b2=self.m.geom_bodyid[c.geom1],self.m.geom_bodyid[c.geom2]
   if self.ob in [b1,b2]:cs.append((self.m.geom(c.geom1).name,self.m.geom(c.geom2).name,round(c.dist,4)))
  print('contacts',cs,flush=True)
 def pic(self,tag):
  for cam in ['side','front','top']:
   Image.fromarray(self.s.render(cam)).save('/app/output/'+tag+'_'+cam+'.png')

def hand(f=.8,thumb=(1.2,0,.5,0,.5)):
 h=np.zeros(22);h[:5]=thumb
 for j in [5,9,13,18]:h[j]=f;h[j+2]=f;h[j+3]=f
 return h

if __name__=='__main__':
 c=Controller();c.hold(60);c.info('settled')
 R=np.array([[0.,1,0],[0,0,-1],[-1,0,0]])
 c.move(np.array([.07,.18,.65]),R,hand(0, (0,0,0,0,0)),150)
